require_once __DIR__ . '/auth.php';$user=require_user($conn);$message=$_SESSION['profile_message']??'';unset($_SESSION['profile_message']);if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$picture=$user['profile_picture']??null;$file=$_FILES['profile_picture']??null;if($file&&$file['error']!==UPLOAD_ERR_NO_FILE){if($file['error']!==UPLOAD_ERR_OK||$file['size']>5*1024*1024){$_SESSION['profile_message']='Profile pictures must be smaller than 5 MB.';redirect_to('profile.php');}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp'][$mime]??null;if(!$ext){$_SESSION['profile_message']='Use JPG, PNG, GIF, or WebP.';redirect_to('profile.php');}$new='profile/'.bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],__DIR__.'/'.$new)){$_SESSION['profile_message']='Could not save the profile picture.';redirect_to('profile.php');}$picture=$new;}$stmt=$conn->prepare('UPDATE users SET profile_picture=? WHERE id=?');$stmt->bind_param('si',$picture,$user['id']);$stmt->execute();$_SESSION['profile_message']='Profile updated.';redirect_to('profile.php');}
$stmt=$conn->prepare('SELECT id,username,email,profile_picture FROM users WHERE id=?');$stmt->bind_param('i',$user['id']);$stmt->execute();$profile=$stmt->get_result()->fetch_assoc();$stmt=$conn->prepare('SELECT id,upload_video,title,description FROM uploaded_videos WHERE username=? ORDER BY created_at DESC');$stmt->bind_param('s',$user['username']);$stmt->execute();$videos=$stmt->get_result();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile · WatchWave</title><link rel="stylesheet" href="css/style.css"></head><body><nav class="flex-div"><div class="nav-left flex-div"><img src="images/logo.png" class="logo" alt="WatchWave"></div><div class="nav-right"><a class="btn" href="home.php">Watch</a><a class="btn" href="upload.php">Upload</a><?php if($user['is_admin']): ?><a class="btn" href="admin.php">Moderation</a><?php endif; ?><a class="btn" href="logout.php">Log out</a></div></nav><main class="profile-container"><div style="text-align:center"><?php if($profile['profile_picture']): ?><img class="profile-picture" src="<?=e($profile['profile_picture'])?>" alt="Profile picture"><?php endif; ?><h1><?=e($profile['username'])?></h1><p><?=e($profile['email']?:'WatchWave creator')?></p><?php if($message): ?><div class="alert"><?=e($message)?></div><?php endif; ?><form method="post" enctype="multipart/form-data" style="justify-content:center"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="file" name="profile_picture" accept="image/jpeg,image/png,image/gif,image/webp" required><button class="btn" type="submit">Update profile picture</button></form></div><h2>Your videos</h2><div class="video-grid"><?php if(!$videos->num_rows): ?><p>You have not uploaded any videos yet.</p><?php endif; ?><?php while($video=$videos->fetch_assoc()): ?><article class="video-thumbnail"><video controls class="thumbnail-preview"><source src="<?=e($video['upload_video'])?>"></video><div style="padding:0 16px"><h3><?=e($video['title'])?></h3><p><?=e($video['description'])?></p></div></article><?php endwhile; ?></div></main></body></html>
